#!/usr/bin/env bash
# Autogenerated test: runs as the remote user inside a container built from each compatibility image with lean
# installed with default options, after the container-creation script ran.
set -euo pipefail

# shellcheck source=/dev/null
source dev-container-features-test-lib

readonly VOLUME_DIR="/var/lib/lean"
readonly INITIALIZE="/usr/local/share/lean-feature/initialize"
readonly PROXIES=(lean lake leanc leanmake leanchecker leanpkg)

is_mount() {
  grep -q "^[^ ]* [^ ]* [^ ]* [^ ]* $1 " /proc/self/mountinfo
}

# Prints every entry below the volume, relative to it, sorted.
volume_entries() {
  find "${VOLUME_DIR}" -mindepth 1 -printf '%P\n' | sort | paste -sd ' '
}

member_of_lean() {
  [[ " $(id -Gn) " == *" lean "* ]]
}

# Whether a shell started as `bash $1` (-c, or -lc for a login shell) sees the feature's three variables.
shell_has_lean_env() {
  local values
  # The variables expand in the shell that bash starts, not in this one.
  # shellcheck disable=SC2016
  values="$(bash "$1" 'printf "%s|%s|%s" "${ELAN_HOME}" "${LAKE_CACHE_DIR}" "${MATHLIB_CACHE_DIR}"')"
  [[ "${values}" == "/var/lib/lean/elan|/var/lib/lean/cache/lake|/var/lib/lean/cache/mathlib" ]]
}

# Whether the package manager of this image keeps no package index (repository metadata) and no downloaded package.
package_caches_clean() {
  local leftover
  if command -v apt-get >/dev/null; then
    leftover="$(find /var/lib/apt/lists /var/cache/apt/archives \( -name '*_Packages*' -o -name '*.deb' \) \
      -print -quit)"
  elif command -v dnf >/dev/null; then
    leftover="$(find /var/cache/dnf /var/cache/libdnf5 \( -name 'repomd.xml' -o -name '*.rpm' \) -print -quit \
      2>/dev/null || true)"
  elif command -v pacman >/dev/null; then
    leftover="$(find /var/lib/pacman/sync /var/cache/pacman/pkg -mindepth 1 -print -quit)"
  else
    # zypper clean keeps the empty directory /var/cache/zypp/solv; only files are cached data.
    leftover="$(find /var/cache/zypp -type f \( -name 'repomd.xml' -o -name '*.rpm' -o -name 'solv' \) -print -quit \
      2>/dev/null || true)"
  fi
  [[ -z "${leftover}" ]]
}

# Whether elan, run as "$@" --version, reports the release the test expects.
reports_release() {
  local line
  line="$("$@" --version)"
  [[ "${line}" == "elan ${release} "* ]]
}

# Whether elan show, run outside any project, names $1 as the default it resolves from.
default_is() {
  local shown
  shown="$(cd / && elan show)"
  [[ "${shown}" == *"(resolved from default '$1')"* ]]
}

no_image_toolchain() {
  [[ ! -d /usr/local/share/lean/toolchains || -z "$(ls -A /usr/local/share/lean/toolchains)" ]]
}

has_ca_bundle() {
  local bundle
  for bundle in /etc/ssl/certs/ca-certificates.crt /etc/pki/tls/certs/ca-bundle.crt /etc/ssl/ca-bundle.pem; do
    if [[ -s "${bundle}" ]]; then return 0; fi
  done
  return 1
}

# New volume: checked before anything in this test runs elan.
check "${VOLUME_DIR} is a mount of the volume" is_mount "${VOLUME_DIR}"
check "the volume holds only the directories the creation step made and elan's settings" \
  [ "$(volume_entries)" == "cache cache/lake cache/mathlib elan elan/settings.toml elan/toolchains" ]
for dir in elan/toolchains cache/lake cache/mathlib; do
  check "${VOLUME_DIR}/${dir} belongs to the remote user" [ "$(stat -c %u "${VOLUME_DIR}/${dir}")" == "$(id -u)" ]
done
check "the remote user creates files in each directory" \
  bash -c "touch ${VOLUME_DIR}/elan/toolchains/.t ${VOLUME_DIR}/cache/lake/.t ${VOLUME_DIR}/cache/mathlib/.t \
    && rm ${VOLUME_DIR}/elan/toolchains/.t ${VOLUME_DIR}/cache/lake/.t ${VOLUME_DIR}/cache/mathlib/.t"
# An implementation check: the remote user runs the creation script, and only root can change what it does.
check "the creation script is root's, mode 755" [ "$(stat -c '%u %g %a' "${INITIALIZE}")" == "0 0 755" ]

# Remote user root, Remote user in the group.
if [[ "$(id -u)" == "0" ]]; then
  check "the install creates no group lean for root" bash -c '! grep -q "^lean:" /etc/group'
  check "the volume is owned by root and writable by root only" [ "$(stat -c '%u %g %a' "${VOLUME_DIR}")" == "0 0 755" ]
else
  check "the remote user is a member of the group lean" member_of_lean
  check "the volume belongs to the group lean, writable by its members and by no other user" \
    [ "$(stat -c '%G %a' "${VOLUME_DIR}")" == "lean 2775" ]
fi

# Omitted elanVersion. The release the redirect names when the test runs cannot be a literal; a release published
# between the image build and the test fails once.
latest_url="$(curl --proto '=https' -fsS -o /dev/null -w '%{redirect_url}' \
  https://github.com/leanprover/elan/releases/latest)"
release="${latest_url##*/v}"
printf '%s\n' "Expecting elan ${release}"
# Resolved, because Fedora's /usr/local/sbin is a link to bin and comes first on root's PATH.
check "elan runs by name and resolves to /usr/local/bin/elan" \
  [ "$(readlink -f "$(command -v elan)")" == "/usr/local/bin/elan" ]
check "elan is root's and executable by every user" [ "$(stat -c '%u %a' /usr/local/bin/elan)" == "0 755" ]
check "elan --version reports the newest release" reports_release elan
if [[ "$(id -u)" != "0" ]]; then
  check "elan --version reports the newest release as root" reports_release sudo elan
fi
for proxy in "${PROXIES[@]}"; do
  check "${proxy} runs by name and resolves to /usr/local/bin/elan" \
    [ "$(readlink -f "$(command -v "${proxy}")")" == "/usr/local/bin/elan" ]
done

# Omitted defaultToolchain.
check "elan show names stable as the default it resolves from" default_is stable

# Omitted preinstallToolchains.
check "no toolchain is installed into the image" no_image_toolchain
check "no toolchain is linked into elan's home" [ -z "$(ls -A "${VOLUME_DIR}/elan/toolchains")" ]

# Variables in a login shell.
check "each variable has the stated value" shell_has_lean_env -c
check "each variable has the stated value in a login shell" shell_has_lean_env -lc

# Prerequisites.
for command in curl git tar gzip find; do
  check "${command} is installed" command -v "${command}"
done
check "a CA certificate bundle is installed" has_ca_bundle
check "the package manager's cache holds no package index or downloaded package" package_caches_clean

reportResults
